import pandas as pd
sql_query = """
SELECT T1.Name
FROM table_5b6fd6c53269f68ff9917438bca1d1cf T1
JOIN table_eb46adee8e29808d89c3d571adcd69df T2 ON T1.ActorID = T2.ActorID
JOIN table_7094d14dcbfa3921163187bde7597aeb T3 ON T2.MovieID = T3.MovieID
WHERE T3.Title = 'Batman' AND T2.CharacterName = 'Joker'
"""
result_df = execute_sql_query(sql_query)
if not result_df.empty:
    result = {'type': 'string', 'value': f"The actor who played the role of Joker in the movie Batman is {result_df.iloc[0]['Name']}."}
else:
    result = {'type': 'string', 'value': 'No actor found who played the role of Joker in the movie Batman.'}

import pandas as pd
batman_movie_query = """
SELECT MovieID, Title
FROM table_7094d14dcbfa3921163187bde7597aeb
WHERE Title LIKE '%Batman%'
"""
batman_movie = execute_sql_query(batman_movie_query)
if not batman_movie.empty:
    movie_id = batman_movie['MovieID'].iloc[0]
    query = f"""
    SELECT t1.Title, t2.Name as ActorName, t3.CharacterName, t3.screentime
    FROM table_7094d14dcbfa3921163187bde7597aeb t1
    JOIN table_eb46adee8e29808d89c3d571adcd69df t3 ON t1.MovieID = t3.MovieID
    JOIN table_5b6fd6c53269f68ff9917438bca1d1cf t2 ON t3.ActorID = t2.ActorID
    WHERE t1.MovieID = {movie_id}
    AND t3.screentime IS NOT NULL
    AND t3.screentime != ''
    """
    result_df = execute_sql_query(query)
    if not result_df.empty:
        max_screen_time = -1
        longest_character = None
        for _, row in result_df.iterrows():
            screentime = row['screentime']
            try:
                if ':' in screentime:
                    parts = screentime.split(':')
                    if len(parts) == 2:
                        minutes = int(parts[0])
                        seconds = int(parts[1])
                        total_seconds = minutes * 60 + seconds
                    else:
                        total_seconds = int(parts[0]) * 60
                else:
                    total_seconds = int(screentime) * 60
                if total_seconds > max_screen_time:
                    max_screen_time = total_seconds
                    longest_character = row
            except (ValueError, IndexError):
                continue
        if longest_character is not None:
            display_time = f'{max_screen_time // 60}:{max_screen_time % 60:02d}'
            result = {'type': 'string', 'value': f"The character with the longest screen time in '{longest_character['Title']}' is {longest_character['CharacterName']} played by {longest_character['ActorName']} with {display_time} screen time."}
        else:
            result = {'type': 'string', 'value': 'No valid screen time data available for Batman characters.'}
    else:
        result = {'type': 'string', 'value': 'No screen time data available for Batman characters.'}
else:
    result = {'type': 'string', 'value': 'The movie Batman was not found in the database.'}

import pandas as pd
actor_query = """
SELECT ActorID, Name
FROM table_5b6fd6c53269f68ff9917438bca1d1cf
WHERE Name = 'John Travolta'
"""
actor_df = execute_sql_query(actor_query)
if not actor_df.empty:
    actor_id = actor_df['ActorID'].iloc[0]
    movie_query = f"""
    SELECT m.Title, m.Rating, m.ReleaseDate, m.Genre
    FROM table_7094d14dcbfa3921163187bde7597aeb m
    JOIN table_eb46adee8e29808d89c3d571adcd69df c ON m.MovieID = c.MovieID
    WHERE c.ActorID = {actor_id}
    ORDER BY m.Rating DESC
    LIMIT 1
    """
    movie_df = execute_sql_query(movie_query)
    if not movie_df.empty:
        best_movie = movie_df.iloc[0]
        result = {'type': 'string', 'value': f"The highest quality movie starring John Travolta is '{best_movie['Title']}' with a rating of {best_movie['Rating']}."}
    else:
        result = {'type': 'string', 'value': 'No movies found for John Travolta in the database.'}
else:
    result = {'type': 'string', 'value': 'Actor John Travolta not found in the database.'}

