import pandas as pd
actor_query = """
SELECT ActorID
FROM table_5b6fd6c53269f68ff9917438bca1d1cf
WHERE Name = 'Tom Cruise'
"""
actor_df = execute_sql_query(actor_query)
if actor_df.empty:
    result = {'type': 'string', 'value': 'Tom Cruise not found in the database.'}
else:
    actor_id = actor_df['ActorID'].iloc[0]
    movie_query = f"""
    SELECT m.MovieID, m.Title, m.Rating, m.RatingCount, m.Genre, m.ReleaseDate
    FROM table_eb46adee8e29808d89c3d571adcd69df c
    JOIN table_7094d14dcbfa3921163187bde7597aeb m
    ON c.MovieID = m.MovieID
    WHERE c.ActorID = {actor_id}
    ORDER BY m.Rating DESC, m.RatingCount DESC
    LIMIT 1
    """
    movie_df = execute_sql_query(movie_query)
    if movie_df.empty:
        result = {'type': 'string', 'value': 'No movies found starring Tom Cruise.'}
    else:
        best_movie = movie_df.iloc[0]
        result = {'type': 'string', 'value': f"The highest quality movie starring Tom Cruise is '{best_movie['Title']}' with a rating of {best_movie['Rating']} ({best_movie['RatingCount']} ratings). It's a {best_movie['Genre']} movie released on {best_movie['ReleaseDate']}."}

