import pandas as pd


def get_actor_name():
    sql_query = """
        SELECT T1.Name
        FROM table_5b6fd6c53269f68ff9917438bca1d1cf T1
        JOIN table_eb46adee8e29808d89c3d571adcd69df T2 ON T1.ActorID = T2.ActorID
        JOIN table_7094d14dcbfa3921163187bde7597aeb T3 ON T2.MovieID = T3.MovieID
        WHERE T3.Title = 'Batman' AND T2.CharacterName = 'Joker'
    """
    result_df = execute_sql_query(sql_query)
    if not result_df.empty:
        actor_name = result_df['Name'].iloc[0]
        return actor_name
    else:
        return None


actor_name = get_actor_name()
